import java.util.*;

class Twitter {
    private Map<Integer, List<int[]>> tweets;
    private Map<Integer, Set<Integer>> follows;
    private int timestamp;

    public Twitter() {
        tweets = new HashMap<>();
        follows = new HashMap<>();
        timestamp = 0;
    }

    public void postTweet(int userId, int tweetId) {
        tweets.computeIfAbsent(userId, k -> new ArrayList<>()).add(new int[]{timestamp++, tweetId});
    }

    public List<Integer> getNewsFeed(int userId) {
        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> b[0] - a[0]);
        List<int[]> own = tweets.getOrDefault(userId, Collections.emptyList());
        for (int[] t : own) pq.offer(t);
        Set<Integer> followees = follows.getOrDefault(userId, Collections.emptySet());
        for (int fid : followees) {
            List<int[]> fTweets = tweets.getOrDefault(fid, Collections.emptyList());
            for (int[] t : fTweets) pq.offer(t);
        }
        List<Integer> result = new ArrayList<>();
        while (!pq.isEmpty() && result.size() < 10) {
            result.add(pq.poll()[1]);
        }
        return result;
    }

    public void follow(int followerId, int followeeId) {
        if (followerId == followeeId) return;
        follows.computeIfAbsent(followerId, k -> new HashSet<>()).add(followeeId);
    }

    public void unfollow(int followerId, int followeeId) {
        Set<Integer> set = follows.get(followerId);
        if (set != null) set.remove(followeeId);
    }
}
